arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --primary: #000000;
  --accent: #E6FF32;
  --burgundy: #7F2A23;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --radius: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 25px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 50px -10px rgba(0,0,0,0.12);
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--gray-900);
  line-height: 1.6;
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul, ol { list-style: none; }

.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* ===== NAVBAR ===== */
.navbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  padding: 0 24px;
}

.navbar-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.navbar-logo {
  font-weight: 900;
  font-size: 1.5rem;
  letter-spacing: -0.03em;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.navbar-logo .logo-mark {
  width: 32px;
  height: 32px;
  background: var(--primary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1rem;
  font-weight: 900;
}

.navbar-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.navbar-links a {
  font-size: 0.938rem;
  font-weight: 500;
  color: var(--gray-600);
  transition: color var(--transition);
  position: relative;
}

.navbar-links a:hover, .navbar-links a.active {
  color: var(--primary);
}

.navbar-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--primary);
  border-radius: 1px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 28px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 0.938rem;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: var(--accent);
}

.btn-primary:hover {
  background: var(--gray-800);
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: var(--gray-100);
  color: var(--primary);
}

.btn-secondary:hover {
  background: var(--gray-200);
}

.btn-outline {
  border: 2px solid var(--gray-200);
  color: var(--primary);
  background: transparent;
}

.btn-outline:hover {
  border-color: var(--primary);
  background: var(--gray-50);
}

.btn-accent {
  background: var(--accent);
  color: var(--primary);
  font-weight: 700;
}

.btn-accent:hover {
  background: #d4eb2d;
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-white {
  background: var(--white);
  color: var(--primary);
  font-weight: 700;
}

.btn-white:hover {
  background: var(--gray-100);
  transform: translateY(-1px);
}

.btn-lg { padding: 16px 36px; font-size: 1rem; }

.navbar-cta .btn { padding: 10px 24px; font-size: 0.875rem; }

.mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}

.mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--primary);
  border-radius: 2px;
  transition: var(--transition);
}

/* ===== HERO ===== */
.hero {
  padding: 80px 0 60px;
  background: var(--white);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  right: -200px;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero-content {
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.hero h1 {
  font-size: 3.5rem;
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.03em;
  color: var(--primary);
  margin-bottom: 20px;
}

.hero p {
  font-size: 1.2rem;
  color: var(--gray-600);
  max-width: 640px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.hero-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Hero tab switch */
.hero-tabs {
  margin-top: 48px;
}

.hero-tab-controls {
  display: inline-flex;
  background: var(--gray-100);
  border-radius: 50px;
  padding: 4px;
  gap: 4px;
  margin-bottom: 32px;
}

.hero-tab-btn {
  padding: 10px 24px;
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-500);
  transition: all var(--transition);
}

.hero-tab-btn.active {
  background: var(--primary);
  color: var(--accent);
  box-shadow: var(--shadow);
}

.hero-tab-panel {
  display: none;
  animation: fadeSlideUp 0.4s ease;
}

.hero-tab-panel.active { display: block; }

.hero-preview {
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 40px;
  max-width: 900px;
  margin: 0 auto;
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.preview-mockup {
  width: 100%;
}

.preview-mockup-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  background: var(--white);
  border-radius: var(--radius) var(--radius) 0 0;
  border: 1px solid var(--gray-200);
  border-bottom: none;
}

.preview-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
}

.preview-dot:first-child { background: #FF5F57; }
.preview-dot:nth-child(2) { background: #FEBC2E; }
.preview-dot:nth-child(3) { background: #28C840; }

.preview-url {
  flex: 1;
  text-align: center;
  font-size: 0.75rem;
  color: var(--gray-400);
  background: var(--gray-50);
  padding: 4px 12px;
  border-radius: 6px;
  margin-left: 8px;
}

.preview-body {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
  padding: 32px;
  min-height: 240px;
}

.preview-body-creator {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 24px;
}

.preview-sidebar {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.preview-sidebar-item {
  padding: 10px 14px;
  border-radius: 8px;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--gray-500);
  background: var(--gray-50);
}

.preview-sidebar-item.active {
  background: var(--primary);
  color: var(--accent);
}

.preview-main {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.preview-stat-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.preview-stat-card {
  background: var(--gray-50);
  border-radius: var(--radius);
  padding: 16px;
  text-align: center;
}

.preview-stat-card .stat-value {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
}

.preview-stat-card .stat-label {
  font-size: 0.7rem;
  color: var(--gray-500);
  margin-top: 4px;
}

.preview-chart {
  background: var(--gray-50);
  border-radius: var(--radius);
  padding: 20px;
  flex: 1;
  display: flex;
  align-items: flex-end;
  gap: 8px;
}

.chart-bar {
  flex: 1;
  background: var(--accent);
  border-radius: 4px 4px 0 0;
  min-height: 20px;
  transition: height var(--transition);
}

.preview-body-student {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.preview-course-header {
  display: flex;
  align-items: center;
  gap: 16px;
}

.preview-course-thumb {
  width: 80px;
  height: 56px;
  background: linear-gradient(135deg, var(--burgundy), #a83029);
  border-radius: 8px;
}

.preview-course-info h4 {
  font-size: 0.95rem;
  font-weight: 700;
}

.preview-course-info span {
  font-size: 0.75rem;
  color: var(--gray-500);
}

.preview-progress-bar {
  background: var(--gray-100);
  height: 8px;
  border-radius: 4px;
  overflow: hidden;
}

.preview-progress-fill {
  height: 100%;
  background: var(--accent);
  border-radius: 4px;
  width: 65%;
}

.preview-lessons {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.preview-lesson {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 8px;
  background: var(--gray-50);
  font-size: 0.85rem;
}

.lesson-check {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  flex-shrink: 0;
}

.lesson-check.done {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--accent);
}

/* ===== STATS BAR ===== */
.stats-bar {
  background: var(--primary);
  padding: 40px 0;
}

.stats-bar .container {
  display: flex;
  justify-content: center;
  gap: 80px;
  flex-wrap: wrap;
}

.stat-item { text-align: center; }

.stat-number {
  font-size: 2.5rem;
  font-weight: 900;
  color: var(--accent);
  letter-spacing: -0.02em;
  line-height: 1;
}

.stat-label {
  font-size: 0.938rem;
  color: var(--gray-400);
  margin-top: 6px;
  font-weight: 500;
}

/* ===== SECTION COMMON ===== */
.section { padding: 100px 0; }
.section-alt { background: var(--gray-50); }
.section-dark { background: var(--primary); color: var(--white); }

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 60px;
}

.section-header .badge {
  display: inline-block;
  padding: 6px 16px;
  border-radius: 50px;
  font-size: 0.813rem;
  font-weight: 600;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.badge-dark {
  background: var(--gray-900);
  color: var(--accent);
}

.badge-light {
  background: var(--gray-100);
  color: var(--gray-700);
}

.badge-accent {
  background: rgba(230,255,50,0.2);
  color: var(--gray-800);
}

.section-header h2 {
  font-size: 2.5rem;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin-bottom: 16px;
}

.section-header p {
  font-size: 1.1rem;
  color: var(--gray-500);
  line-height: 1.7;
}

.section-dark .section-header p { color: var(--gray-400); }

/* ===== PRODUCT CARDS ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: all var(--transition);
  text-align: center;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
  border-color: transparent;
}

.product-icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  font-size: 1.8rem;
}

.product-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 10px;
}

.product-card p {
  font-size: 0.9rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ===== WHY CHOOSE US TABS ===== */
.why-tabs-nav {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 48px;
}

.why-tab-btn {
  padding: 12px 24px;
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-500);
  background: var(--gray-100);
  transition: all var(--transition);
}

.why-tab-btn.active {
  background: var(--primary);
  color: var(--accent);
}

.why-tab-btn:hover:not(.active) {
  background: var(--gray-200);
}

.why-tab-panel {
  display: none;
  animation: fadeSlideUp 0.35s ease;
}

.why-tab-panel.active { display: block; }

.why-features-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  max-width: 800px;
  margin: 0 auto;
}

.why-feature-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 20px;
  background: var(--white);
  border-radius: var(--radius);
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.why-feature-item:hover {
  box-shadow: var(--shadow);
  border-color: var(--gray-300);
}

.why-feature-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  flex-shrink: 0;
}

.why-feature-item h4 {
  font-size: 0.95rem;
  font-weight: 700;
  margin-bottom: 2px;
}

.why-feature-item p {
  font-size: 0.85rem;
  color: var(--gray-500);
}

/* ===== FEATURE CARDS ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.feature-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  transition: all var(--transition);
}

.feature-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.feature-card .icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.feature-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 10px;
}

.feature-card p {
  font-size: 0.9rem;
  color: var(--gray-500);
  line-height: 1.65;
}

/* Two-column feature */
.features-two-col {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.feature-card-lg {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 40px 32px;
  transition: all var(--transition);
}

.feature-card-lg:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.feature-card-lg .icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.feature-card-lg h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.feature-card-lg p {
  font-size: 0.95rem;
  color: var(--gray-500);
  line-height: 1.7;
}

/* Four col */
.features-four-col {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

/* ===== TESTIMONIALS CAROUSEL ===== */
.testimonials-section { overflow: hidden; }

.testimonial-track-wrapper {
  position: relative;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.testimonial-card {
  flex: 0 0 calc(33.333% - 16px);
  margin: 0 8px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  flex-direction: column;
}

.section-dark .testimonial-card {
  background: var(--gray-800);
  border-color: var(--gray-700);
}

.testimonial-quote {
  font-size: 0.95rem;
  color: var(--gray-600);
  line-height: 1.7;
  flex: 1;
  margin-bottom: 24px;
}

.section-dark .testimonial-quote { color: var(--gray-300); }

.testimonial-tag {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 50px;
  font-size: 0.75rem;
  font-weight: 600;
  background: rgba(230,255,50,0.15);
  color: var(--gray-700);
  margin-bottom: 16px;
  width: fit-content;
}

.section-dark .testimonial-tag {
  background: rgba(230,255,50,0.1);
  color: var(--accent);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.85rem;
  color: var(--gray-600);
}

.section-dark .testimonial-avatar {
  background: var(--gray-700);
  color: var(--gray-300);
}

.testimonial-name {
  font-weight: 700;
  font-size: 0.9rem;
}

.testimonial-role {
  font-size: 0.8rem;
  color: var(--gray-500);
}

.section-dark .testimonial-role { color: var(--gray-400); }

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 40px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--gray-200);
  background: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  font-size: 1.1rem;
  color: var(--gray-600);
}

.carousel-btn:hover {
  background: var(--primary);
  color: var(--accent);
  border-color: var(--primary);
}

.section-dark .carousel-btn {
  border-color: var(--gray-600);
  background: var(--gray-800);
  color: var(--gray-300);
}

.section-dark .carousel-btn:hover {
  background: var(--accent);
  color: var(--primary);
  border-color: var(--accent);
}

/* ===== PRICING ===== */
.pricing-content {
  text-align: center;
}

.pricing-highlight {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 20px 32px;
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  margin-bottom: 32px;
}

.pricing-highlight .price {
  font-size: 2.5rem;
  font-weight: 900;
  color: var(--primary);
}

.pricing-highlight .price-info {
  text-align: left;
}

.pricing-highlight .price-info span {
  font-size: 0.85rem;
  color: var(--gray-500);
  display: block;
}

.pricing-highlight .price-info strong {
  font-size: 0.95rem;
  color: var(--gray-800);
}

.pricing-features {
  display: flex;
  gap: 32px;
  justify-content: center;
  flex-wrap: wrap;
  margin: 32px 0 40px;
}

.pricing-feature {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.938rem;
  color: var(--gray-600);
}

.pricing-feature .check {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
}

.pricing-enterprise {
  background: var(--gray-900);
  border-radius: var(--radius-lg);
  padding: 48px;
  margin-top: 48px;
  color: var(--white);
}

